const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').split(/\s+/).filter(Boolean).map(Number);

let idx = 0;
const N = input[idx++];
const adj = Array.from({ length: N + 1 }, () => []);

for (let i = 0; i < N - 1; i++) {
  const a = input[idx++];
  const b = input[idx++];
  adj[a].push(b);
  adj[b].push(a);
}

const size = new Array(N + 1).fill(1);
const parent = new Array(N + 1).fill(0);
const visited = new Array(N + 1).fill(false);

// DFS iterativo
const stack = [1];
visited[1] = true;
const order = [];

while (stack.length) {
  const u = stack.pop();
  order.push(u);
  for (const v of adj[u]) {
    if (!visited[v]) {
      visited[v] = true;
      parent[v] = u;
      stack.push(v);
    }
  }
}

// processar em ordem inversa (folhas para raiz)
let ans = Infinity;
for (let i = order.length - 1; i >= 0; i--) {
  const u = order[i];
  if (u !== 1) {
    const diff = Math.abs(N - 2 * size[u]);
    if (diff < ans) ans = diff;
    size[parent[u]] += size[u];
  }
}

console.log(ans);
